public class ReferenceCheck { public static void main(String[] args) {
 int[] values={4,7,7,2,9};
 Check.eq("window",WindowCounts.countAtLeast(values,1,4,7),2);
 Check.eq("whole",WindowCounts.countAtLeast(values,0,5,7),3);
 Check.eq("empty",WindowCounts.countAtLeast(values,3,3,7),0);
 Check.eq("last",WindowCounts.countAtLeast(values,4,5,9),1);
 Check.eq("unchanged",java.util.Arrays.toString(values),"[4, 7, 7, 2, 9]");
 Check.fails("null",NullPointerException.class,()->WindowCounts.countAtLeast(null,0,0,0));
 Check.fails("negative",IllegalArgumentException.class,()->WindowCounts.countAtLeast(values,-1,0,0));
 Check.fails("beyond",IllegalArgumentException.class,()->WindowCounts.countAtLeast(values,0,6,0));
 Check.fails("reversed",IllegalArgumentException.class,()->WindowCounts.countAtLeast(values,3,2,0));
}}

public class ReferenceCheck { public static void main(String[] args) {
 GridKey a=new GridKey(0,31), b=new GridKey(0,31), c=new GridKey(0,31), collision=new GridKey(1,0);
 Check.eq("coordinates",a.row()+","+a.column(),"0,31");
 Check.eq("identity",a==b,false);
 Check.eq("reflexive",a.equals(a),true);
 Check.eq("symmetric",a.equals(b)&&b.equals(a),true);
 Check.eq("transitive",a.equals(b)&&b.equals(c)&&a.equals(c),true);
 Check.eq("null",a.equals(null),false);
 Check.eq("unrelated",a.equals("0,31"),false);
 Check.eq("different-column",a.equals(new GridKey(0,30)),false);
 Check.eq("collision",a.hashCode()==collision.hashCode()&&!a.equals(collision),true);
 java.util.Set<GridKey> keys=new java.util.HashSet<>();keys.add(a);keys.add(b);keys.add(collision);
 Check.eq("set-size",keys.size(),2);
}}

