public class ReferenceCheck { public static void main(String[] args) {
 CapacityShelf s=new CapacityShelf(3);Check.eq("add-first",s.add("ink"),true);s.add("chalk");s.add("wax");
 Check.eq("duplicate",s.add("ink"),false);Check.eq("full",s.add("clay"),false);Check.eq("remove-middle",s.remove("chalk"),true);s.add("clay");
 Check.eq("order",java.util.Arrays.toString(s.snapshot()),"[ink, wax, clay]");Check.eq("size",s.size(),3);
 String[] copy=s.snapshot();copy[0]="changed";Check.eq("defensive-copy",s.snapshot()[0],"ink");
 Check.eq("absent",s.remove("missing"),false);s.remove("ink");s.remove("clay");Check.eq("ends",java.util.Arrays.toString(s.snapshot()),"[wax]");
 Check.eq("zero-capacity",new CapacityShelf(0).add("x"),false);Check.fails("negative-capacity",IllegalArgumentException.class,()->new CapacityShelf(-1));
 Check.fails("null-label",IllegalArgumentException.class,()->s.add(null));Check.fails("empty-label",IllegalArgumentException.class,()->s.remove(""));
}}

public class ReferenceCheck { public static void main(String[] args) {
 AlertRule high=new HighAlert(10),low=new LowAlert(10);
 Check.eq("high",high.matches(9)+","+high.matches(10)+","+high.matches(11),"false,false,true");
 Check.eq("low",low.matches(9)+","+low.matches(10)+","+low.matches(11),"true,false,false");
 java.util.List<AlertRule> original=new java.util.ArrayList<>();original.add(new HighAlert(5));original.add(new LowAlert(10));RuleSet set=new RuleSet(original);original.clear();
 Check.eq("composed",set.matchingRules(7),2);Check.eq("empty",new RuleSet(java.util.List.of()).matchingRules(7),0);
 Check.fails("null-rules",NullPointerException.class,()->new RuleSet(null));
 Check.fails("null-element",NullPointerException.class,()->new RuleSet(java.util.Arrays.asList((AlertRule)null)));
}}

import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
public class ReferenceCheck {
 static class Tracked extends StringReader {boolean closed;Tracked(String s){super(s);}@Override public void close(){closed=true;super.close();}}
 public static void main(String[] args)throws Exception {
  Tracked borrowed=new Tracked("north|12\nsouth|-4\nnorth|0\n");Check.eq("parsed",ReadingExport.parse(borrowed).toString(),"[Reading[channel=north, value=12], Reading[channel=south, value=-4], Reading[channel=north, value=0]]");Check.eq("borrowed-open",borrowed.closed,false);
  Check.eq("empty",ReadingExport.parse(new StringReader("")).size(),0);
  Check.eq("bounds",ReadingExport.parse(new StringReader("a|-50\nb|150")).size(),2);
  String[] bad={"a|1\n","a|1\n\n","a|01","a|+2","a|151","a|-51","A|2","a|1|2","a|99999999999999999"};
  // A terminal newline ends a valid record; a second newline is an actual blank line.
  Check.eq("terminal-newline",ReadingExport.parse(new StringReader(bad[0])).size(),1);
  for(int i=1;i<bad.length;i++){String s=bad[i];Check.fails("malformed-"+i,ReadingFormatException.class,()->ReadingExport.parse(new StringReader(s)));}
  try{ReadingExport.parse(new StringReader("a|1\n\n"));throw new AssertionError();}catch(ReadingFormatException e){Check.eq("line-number",e.lineNumber(),2);}
  Reader broken=new Reader(){public int read(char[] c,int o,int l)throws IOException{throw new IOException("read failed");}public void close(){}};
  Check.fails("io-failure",IOException.class,()->ReadingExport.parse(broken));
  Path dir=Files.createTempDirectory("reading-reference-");Path input=dir.resolve("source.data"),output=dir.resolve("result.out");
  try{Files.writeString(input,"north|12\nsouth|-4\nnorth|0\n",StandardCharsets.UTF_8);ReadingExport.convert(input,output);Check.eq("formatted",Files.readString(output),"NORTH:12\nSOUTH:-4\nNORTH:0\n");Files.writeString(input,"north|12\nBAD");Files.writeString(output,"KEEP");Check.fails("parse-preserves-output",ReadingFormatException.class,()->ReadingExport.convert(input,output));Check.eq("preserved",Files.readString(output),"KEEP");}finally{Files.deleteIfExists(input);Files.deleteIfExists(output);Files.deleteIfExists(dir);}
 }
}

