public class ReferenceCheck {public static void main(String[] args)throws Exception{
 MaterialKey a=new MaterialKey("EAST","resin"),b=new MaterialKey("EAST","resin"),c=new MaterialKey("EAST","resin");
 Check.eq("key-contract",a!=b&&a.equals(b)&&b.equals(a)&&b.equals(c)&&a.equals(c)&&a.hashCode()==b.hashCode(),true);
 Check.eq("key-not-null",a.equals(null),false);Check.eq("key-different",a.equals(new MaterialKey("EAST","wire")),false);
 Check.fails("bad-key",IllegalArgumentException.class,()->new MaterialKey("east","resin"));Check.fails("bad-units",IllegalArgumentException.class,()->new StockEntry(a,1001));
 String source="EAST~resin~4\nWEST~wire~9\nEAST~resin~7\nEAST~wire~0\n";List<StockEntry> entries=LedgerParser.read(new StringReader(source));
 Check.eq("parsed",entries.size(),4);Check.eq("totals",LedgerTotals.lines(entries).toString(),"[EAST/resin=11, EAST/wire=0, WEST/wire=9]");Check.eq("empty",LedgerTotals.lines(List.of()).size(),0);
 String[] bad={"EAST~resin~01","EAST~resin~+1","EAST~resin~-1","EAST~resin~1001","EAST~resin~999999999999999","EAST~resin~1~2",""};
 for(int i=0;i<bad.length;i++){String value="EAST~wire~1\n"+bad[i]+"\n";try{LedgerParser.read(new StringReader(value));throw new AssertionError();}catch(IOException e){Check.eq("invalid-"+i,e.getMessage(),"Invalid material record at line 2");}}
 Path dir=Files.createTempDirectory("ledger-reference-");Path input=dir.resolve("workshop.data"),output=dir.resolve("totals.out");ByteArrayOutputStream out=new ByteArrayOutputStream(),err=new ByteArrayOutputStream();PrintStream stdout=new PrintStream(out,true,StandardCharsets.UTF_8),stderr=new PrintStream(err,true,StandardCharsets.UTF_8);
 try{Files.writeString(input,source);Check.eq("cli-success",LedgerCli.run(new String[]{input.toString(),output.toString()},stdout,stderr),0);Check.eq("cli-message",out.toString(StandardCharsets.UTF_8).trim(),"Wrote 3 totals.");Check.eq("cli-output",Files.readString(output),"EAST/resin=11\nEAST/wire=0\nWEST/wire=9\n");Check.eq("cli-usage",LedgerCli.run(new String[]{},stdout,stderr),2);Check.eq("cli-missing",LedgerCli.run(new String[]{dir.resolve("missing").toString(),output.toString()},stdout,stderr),1);Files.writeString(input,"bad");Files.writeString(output,"KEEP");Check.eq("cli-malformed",LedgerCli.run(new String[]{input.toString(),output.toString()},stdout,stderr),1);Check.eq("cli-preserves",Files.readString(output),"KEEP");}finally{stdout.close();stderr.close();Files.deleteIfExists(input);Files.deleteIfExists(output);Files.deleteIfExists(dir);}
}}

import java.io.*;import java.nio.file.*;import java.util.*;
public class ReferenceCheck {
 static class Tracked extends StringReader {boolean closed;Tracked(String s){super(s);}@Override public void close(){closed=true;super.close();}}
 public static void main(String[] args)throws Exception {
  String source="STUDIO^1^400\nLAB^1^800\nSTUDIO^2^900\nLAB^2^700\n";Tracked borrowed=new Tracked(source);List<Sample> samples=AirAudit.parse(borrowed);
  Check.eq("report",AirAudit.report(samples,700).toString(),"[LAB count=2 peak=800 alerts=1, STUDIO count=2 peak=900 alerts=1]");Check.eq("borrowed-open",borrowed.closed,false);Check.eq("empty",AirAudit.report(List.of(),0).size(),0);
  String[] bad={"LAB^1^2\nLAB^1^3","LAB^1^2\n\n","LAB^01^2","LAB^0^2","LAB^1001^2","LAB^1^-1","LAB^1^5001","lab^1^2","LAB^1^2^3","LAB^1^+2"};
  for(int i=0;i<bad.length;i++){String s=bad[i];Check.fails("malformed-"+i,SampleFormatException.class,()->AirAudit.parse(new StringReader(s)));}
  try{AirAudit.parse(new StringReader("LAB^1^2\nLAB^1^3"));throw new AssertionError();}catch(SampleFormatException e){Check.eq("duplicate-line",e.lineNumber(),2);}
  Check.eq("different-zones",AirAudit.parse(new StringReader("LAB^1^2\nSTUDIO^1^3")).size(),2);
  Check.fails("threshold-negative",IllegalArgumentException.class,()->AirAudit.report(samples,-1));Check.fails("threshold-high",IllegalArgumentException.class,()->AirAudit.report(samples,5001));
  Reader broken=new Reader(){public int read(char[] c,int o,int l)throws IOException{throw new IOException("broken");}public void close(){}};Check.fails("io-failure",IOException.class,()->AirAudit.parse(broken));
  Path dir=Files.createTempDirectory("air-reference-");Path input=dir.resolve("air.data"),output=dir.resolve("audit.out");PrintStream err=new PrintStream(new ByteArrayOutputStream());
  try{Files.writeString(input,source);Check.eq("cli-success",AirAuditCli.run(new String[]{input.toString(),output.toString(),"700"},err),0);Check.eq("formatted",Files.readString(output),"LAB count=2 peak=800 alerts=1\nSTUDIO count=2 peak=900 alerts=1\n");Check.eq("cli-usage",AirAuditCli.run(new String[]{},err),2);Check.eq("cli-threshold",AirAuditCli.run(new String[]{input.toString(),output.toString(),"+7"},err),2);Check.eq("cli-missing",AirAuditCli.run(new String[]{dir.resolve("missing").toString(),output.toString(),"700"},err),1);Files.writeString(input,"bad");Files.writeString(output,"KEEP");Check.eq("cli-malformed",AirAuditCli.run(new String[]{input.toString(),output.toString(),"700"},err),1);Check.eq("preserved",Files.readString(output),"KEEP");}finally{err.close();Files.deleteIfExists(input);Files.deleteIfExists(output);Files.deleteIfExists(dir);}
 }
}

import java.io.*;import java.nio.file.*;import java.util.*;
public class ReferenceCheck {public static void main(String[] args)throws Exception{
 List<List<String>> batches=List.of(List.of("lumen","ink","lumen"),List.of("ink","glow"),List.of("glow","lumen"));
 Check.eq("completed-counts",NoteIndex.count(batches).toString(),"{glow=2, ink=2, lumen=3}");Check.eq("empty",NoteIndex.count(List.of()).size(),0);Check.eq("empty-batch",NoteIndex.count(List.of(List.of())).size(),0);
 TokenCounter counter=new TokenCounter();counter.record("ink");Map<String,Long> snapshot=counter.snapshot();snapshot.put("ink",99L);Check.eq("snapshot-isolation",counter.snapshot().get("ink"),1L);
 Check.fails("invalid-token",IllegalArgumentException.class,()->NoteIndex.count(List.of(List.of("Bad"))));Check.fails("null-batch",NullPointerException.class,()->NoteIndex.count(Arrays.asList((List<String>)null)));
 Thread interrupted=new Thread(()->{Thread.currentThread().interrupt();try{NoteIndex.count(List.of(java.util.Collections.nCopies(100000,"ink")));throw new AssertionError("returned partial counts");}catch(InterruptedException expected){}});final Throwable[] failure={null};interrupted.setUncaughtExceptionHandler((t,e)->failure[0]=e);interrupted.start();interrupted.join();Check.eq("interrupted-propagates",failure[0]==null,true);
 Path dir=Files.createTempDirectory("notes-reference-");Path a=dir.resolve("one.data"),b=dir.resolve("two.data");ByteArrayOutputStream out=new ByteArrayOutputStream(),err=new ByteArrayOutputStream();PrintStream stdout=new PrintStream(out),stderr=new PrintStream(err);
 try{Files.writeString(a,"lumen\nink\nlumen\n");Files.writeString(b,"ink\nglow\n");Check.eq("cli-success",NoteIndexCli.run(new String[]{a.toString(),b.toString()},stdout,stderr),0);Check.eq("cli-output",out.toString(java.nio.charset.StandardCharsets.UTF_8),"glow=1\nink=2\nlumen=2\n");Check.eq("cli-usage",NoteIndexCli.run(new String[]{},stdout,stderr),2);out.reset();Files.writeString(b,"ink\nBAD\n");Check.eq("cli-invalid",NoteIndexCli.run(new String[]{a.toString(),b.toString()},stdout,stderr),1);Check.eq("no-partial-output",out.size(),0);Check.eq("cli-missing",NoteIndexCli.run(new String[]{dir.resolve("missing").toString()},stdout,stderr),1);}finally{stdout.close();stderr.close();Files.deleteIfExists(a);Files.deleteIfExists(b);Files.deleteIfExists(dir);}
}}
